    .wa-person-meta { margin: .55rem 0; color: var(--wa-muted); }
    .wa-meter-row {
      display: grid;
      grid-template-columns: 3.3rem minmax(0, 1fr) 4.6rem;
      align-items: center;
      gap: .45rem;
      margin: .34rem 0;
    }
    .wa-meter {
      position: relative;
      height: .42rem;
      overflow: hidden;
      border-radius: 999px;
      background: rgba(255, 255, 255, .07);
    }
    .wa-meter > span {
      position: absolute;
      left: 50%;
      top: 0;
      bottom: 0;
      width: 0;
      border-radius: inherit;
      background: linear-gradient(90deg, var(--wa-soul), var(--wa-blue));
      transition: width .3s ease, left .3s ease;
    }
    .wa-meter > span[data-negative="true"] { background: linear-gradient(90deg, var(--wa-alert), #d485ff); }
    .wa-meter-text { color: var(--wa-muted); font-size: .75rem; text-align: right; }
    .wa-edge {
      padding: .55rem 0;
      border-top: 1px dashed rgba(91, 197, 255, .15);
    }
    .wa-edge:first-child { border-top: 0; padding-top: 0; }
    .wa-event-id { color: var(--wa-soul); font-weight: 700; letter-spacing: .08em; }
    .wa-list { margin: .3rem 0 0; padding-left: 1.15rem; }
    .wa-list li + li { margin-top: .25rem; }
    .wa-foot { padding: .55rem .9rem .75rem; color: var(--wa-muted); font-size: .75rem; }
    .wa-btn {
      margin-top: .55rem;
      padding: .42rem .8rem;
      border: 1px solid rgba(91, 197, 255, .45);
      border-radius: 999px;
      color: var(--wa-blue-soft);
      background: rgba(91, 197, 255, .08);
      font: inherit;
      font-size: .8rem;
      cursor: pointer;
    }
    .wa-btn:hover:not(:disabled), .wa-btn:focus-visible:not(:disabled) {
      border-color: var(--wa-blue);
      color: var(--wa-text);
      background: rgba(91, 197, 255, .16);
    }
    .wa-btn:disabled { opacity: .45; cursor: not-allowed; }
    .wa-error {
      margin: .75rem;
      padding: .7rem;
      border: 1px dashed var(--wa-alert);
      border-radius: 9px;
      color: #ffc3cc;
    }
    @keyframes wa-breathe {
      0%, 100% { opacity: .64; transform: scale(.92); }
      50% { opacity: 1; transform: scale(1.08); }
    }
    @keyframes wa-alert {
      0%, 100% { box-shadow: 0 0 0 rgba(255, 113, 133, 0); }
      50% { box-shadow: 0 0 16px rgba(255, 113, 133, .14); }
    }
    @media (max-width: 600px) {
      .wa-grid { grid-template-columns: 1fr; }
      .wa-card--wide { grid-column: auto; }
